import 'package:flutter/material.dart';
import '../../models/belanjaku/product_model.dart';
import '../../services/belanjaku/product_service.dart';
import '../../services/belanjaku/cart_service.dart';
import '../../widgets/belanjaku/product_card.dart';
import 'product_detail_screen.dart';
class BelanjakuProductListScreen extends StatelessWidget { const BelanjakuProductListScreen({super.key, required this.category, required this.onCartChanged}); final String category; final VoidCallback onCartChanged; @override Widget build(BuildContext context) => Scaffold(appBar: AppBar(title: Text(category)), body: StreamBuilder<List<BelanjakuProduct>>(stream: category == 'Semua' ? BelanjakuProductService().watchActiveProducts() : BelanjakuProductService().watchCategory(category), builder: (context, snap) { if (snap.hasError) return const Center(child: Text('Produk belum dapat dimuat.')); if (!snap.hasData) return const Center(child: CircularProgressIndicator()); final list = snap.data!; if (list.isEmpty) return const Center(child: Padding(padding: EdgeInsets.all(24), child: Text('Belum ada produk pada kategori ini.', textAlign: TextAlign.center))); return GridView.builder(padding: const EdgeInsets.all(14), gridDelegate: const SliverGridDelegateWithMaxCrossAxisExtent(maxCrossAxisExtent: 220, mainAxisExtent: 285, crossAxisSpacing: 12, mainAxisSpacing: 12), itemCount: list.length, itemBuilder: (context, i) { final p = list[i]; return BelanjakuProductCard(product: p, onTap: () => Navigator.push(context, MaterialPageRoute(builder: (_) => BelanjakuProductDetailScreen(product: p, onCartChanged: onCartChanged))), onAdd: p.isAvailable ? () { BelanjakuCartService.instance.add(p); onCartChanged(); ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Ditambahkan ke keranjang'))); } : null); }); })); }
